def decode_source(key):
    return zlib.decompress(
        base64.b85decode(BUNDLED_SOURCES[key].encode("ascii"))
    ).decode("utf-8")


def execute_module(key, module_name=None, source_override=None):
    source = source_override if source_override is not None else decode_source(key)
    actual_name = module_name or ("foodwar_afr_" + key)
    module = types.ModuleType(actual_name)
    module.__file__ = os.path.join(SCRIPT_DIR, "<bundled_" + key + ".py>")
    module.__package__ = ""
    sys.modules[actual_name] = module
    exec(compile(source, "<bundled:" + key + ">", "exec"), module.__dict__)
    return module


def main():
    print("\n=== Loading Standalone Assistant/Farmer/Rider Bundle ===\n")
    standard = {
        key: execute_module(key)
        for key in (
            "basic_characters", "seven_roles", "sentry", "fertilizer_injector"
        )
    }
    orchestrator = execute_module("orchestrator")

    orchestrator.resolve_source = lambda label: label
    orchestrator.load_standard_module = lambda module_name, label: standard[label]

    def load_side_effect(label, module_name, filepath):
        source = orchestrator.transform_side_effect_source(label, decode_source(label))
        return execute_module(label, module_name=module_name, source_override=source)

    orchestrator.load_side_effect_module = load_side_effect
    orchestrator.SOURCE_CANDIDATES = {
        key: (key,)
        for key in (
            "basic_characters", "seven_roles", "sentry",
            "fertilizer_injector", "boombuggy",
        )
    }

    orchestrator.SCRIPT_DIR = SCRIPT_DIR
    orchestrator.OUTPUT_DIR = os.path.join(SCRIPT_DIR, "generated_role_tool_renders")
    orchestrator.OUTPUT_BLEND = os.path.join(
        orchestrator.OUTPUT_DIR, "FTF_AssistantFarmerRider_Tools.blend"
    )
    orchestrator.OUTPUTS = {
        "overview": os.path.join(orchestrator.OUTPUT_DIR, "FTF_AssistantFarmerRider_Overview.png"),
        "assistant": os.path.join(orchestrator.OUTPUT_DIR, "FTF_Assistant_Sentry.png"),
        "farmer": os.path.join(orchestrator.OUTPUT_DIR, "FTF_Farmer_FertilizerInjector.png"),
        "rider": os.path.join(orchestrator.OUTPUT_DIR, "FTF_Rider_BoomBuggy.png"),
    }

    orchestrator.main()


if __name__ == "__main__":
    main()
